select jsonb_build_object('checked_at',clock_timestamp(),'expected',count(*),'exact',count(*)filter(where exact),'mismatches',coalesce(jsonb_agg(ref)filter(where not coalesce(exact,false)),'[]')) as verification from(select 'catalog_work_descriptions:1' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987147012 and t.language='nl')='{"text":"Antony Beevor volgt de invasie van Normandië vanaf de landingen op 6 juni 1944 tot de bevrijding van Parijs. Hij kijkt niet alleen naar militaire plannen en de onderlinge spanningen tussen bevelhebbers, maar ook naar de ervaringen van soldaten en Franse burgers. Dagboeken, brieven en archiefmateriaal brengen die verschillende perspectieven samen. Het boek maakt duidelijk hoe zwaar de gevechten in Noord-Frankrijk waren, ook achter het bekende beeld van bevrijding. De operatie wordt beschreven als een reeks beslissingen met uiteenlopende menselijke gevolgen.","work_id":987147012,"evidence":[{"note":"Retain Work3283 D-Day / Antony Beevor; exact Dutch D-Day ISBN 9789026323157 Paperback. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-029.json. No new Work, changed first-publication year, merged author, additional Dutch availability or taste classification is proposed.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p325712476"],"reference":"work:3283","checked_at":"2026-11-03T09:35:36.993Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-029.json","sources":["https://openlibrary.org/works/OL1881615W","https://data.bibliotheken.nl/id/nbt/p325712476"]},{"note":"Exact bound prior bulk-source attempt retained. No verified asset imported; existing shared resolver retained. Hosted exact-edition decoded front or documentedneutralplaceholder stillrequired.","type":"no_verified_cover_asset_retained","isbn13":"97