rt echter de verhoudingen in de omgeving. Inti vreest dat haar wolven de schuld zullen krijgen en moet bepalen hoe ver zij gaat om hen te beschermen. Haar overtuiging botst zo met vragen waarop zij zelf nog geen zeker antwoord heeft.","work_id":987147019,"evidence":[{"note":"Retain Work5028 Once There Were Wolves / Charlotte McConaghy; exact Dutch Ooit waren er wolven ISBN 9789044650365 Paperback. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-029.json. No new Work, changed first-publication year, merged author, additional Dutch availability or taste classification is proposed.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p435365215"],"reference":"work:5028","checked_at":"2026-11-03T09:35:36.993Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-029.json","sources":["https://openlibrary.org/works/OL22440938W","https://data.bibliotheken.nl/id/nbt/p435365215"]},{"note":"Exact bound prior bulk-source attempt retained. No verified asset imported; existing shared resolver retained. Hosted exact-edition decoded front or documentedneutralplaceholder stillrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789044650365","status":"no_verified_asset_retained","attempts":[{"status":"bulk_source_failure_no_retry","coverId":12817053,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:35:36.995Z","editionKey":"/books/OL38581180M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL22440938W","reviewed_at":"2026-11-03T09:35:36.993+00:00","source_name":"Gecontroleerde boek- en