ntvouwt Florence Knapp drie verschillende versies van het gezinsleven over een periode van vijfendertig jaar. De gekozen naam werkt door in omstandigheden die al door controle en huiselijk geweld zijn getekend. De roman onderzoekt hoeveel ruimte er voor eigen keuzes kan ontstaan binnen een leven dat door anderen lijkt vastgelegd.","work_id":987147024,"evidence":[{"note":"Retain Work5834 The Names / Florence Knapp; exact Dutch De namen ISBN 9789402716856 Paperback. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-030.json. No new Work, changed first-publication year, merged author, additional Dutch availability or taste classification is proposed.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p444165584"],"reference":"work:5834","checked_at":"2026-11-03T09:35:36.993Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-030.json","sources":["https://openlibrary.org/works/OL42406530W","https://data.bibliotheken.nl/id/nbt/p444165584"]},{"note":"Exact bound prior bulk-source attempt retained. No verified asset imported; existing shared resolver retained. Hosted exact-edition decoded front or documentedneutralplaceholder stillrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789402716856","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15146237,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:35:36.995Z","editionKey":"/books/OL60693552M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL42406530W","reviewed_at":"2026-